{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "Launch configuration does not enable EBS volume encryption",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "HIGH",
      "explanation": "The launch configuration does not specify encryption for EBS volumes. Unencrypted volumes can expose sensitive data if compromised."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"levelup-launchconfig\" {\n  name_prefix     = \"levelup-launchconfig\"\n  image_id        = lookup(var.AMIS, var.AWS_REGION)\n  instance_type   = \"t2.micro\"\n  key_name        = aws_key_pair.levelup_key.key_name\n\n  ebs_block_device {\n    device_name           = \"/dev/xvda\"\n    volume_size           = 8\n    volume_type           = \"gp2\"\n    encrypted             = true\n  }\n}",
  "fix_summary": "Added an `ebs_block_device` block to enable encryption for the root EBS volume."
}
